import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Ky-Ipuyb.js";const m=JSON.parse('{"title":"RmlUi 源码目录","description":"","frontmatter":{"lang":"zh-CN","sourcePath":"docs/rmlui/source-layout.zh-CN.md"},"headers":[],"relativePath":"zh/rmlui/source-layout.md","filePath":"zh/rmlui/source-layout.md"}'),r={name:"zh/rmlui/source-layout.md"};function a(s,t,i,l,n,p){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="rmlui-源码目录" tabindex="-1">RmlUi 源码目录 <a class="header-anchor" href="#rmlui-源码目录" aria-label="Permalink to &quot;RmlUi 源码目录&quot;">​</a></h1><p><code>packages/sfml.js-rmlui</code> 按职责组织 Native 绑定、TypeScript 接口和测试。新增实现应放入对应模块，相关头文件与实现文件放在一起。</p><table tabindex="0"><thead><tr><th>目录</th><th>职责</th></tr></thead><tbody><tr><td><code>runtime/</code></td><td>初始化、Context、运行时状态、能力查询、回调生命周期、Plugin、Debugger</td></tr><tr><td><code>dom/documents/</code></td><td>文档、Factory、属性集合、XML 解析</td></tr><tr><td><code>dom/elements/</code></td><td>Element、布局、滚动、元素实例化、SVG 和 Lottie</td></tr><tr><td><code>dom/controls/</code></td><td>表单、文本控件、选项、面板</td></tr><tr><td><code>data/</code></td><td>数据模型、类型注册、地址、成员、批处理、诊断</td></tr><tr><td><code>events/</code></td><td>事件、监听器、分发和实例化</td></tr><tr><td><code>style/properties/</code></td><td>Property、解析器、规范、样式表</td></tr><tr><td><code>style/effects/</code></td><td>装饰器、过滤器、效果值及其回调</td></tr><tr><td><code>style/values/</code></td><td>计算样式、样式结构、变换及映射视图</td></tr><tr><td><code>animation/</code></td><td>动画、过渡、补间及值回调</td></tr><tr><td><code>rendering/</code></td><td>渲染管理、几何、纹理、图层、资源和 SFML 渲染适配</td></tr><tr><td><code>fonts/</code></td><td>字体加载、FreeType／HarfBuzz／位图引擎、测量、字形及字体效果</td></tr><tr><td><code>scripting/</code></td><td>脚本接口、宿主和脚本对象</td></tr><tr><td><code>scripting/lua/</code></td><td>Lua 宿主、模型、值、函数和实例化</td></tr><tr><td><code>platform/</code></td><td>SFML 系统适配、输入、文本输入、窗口密度</td></tr><tr><td><code>io/</code></td><td>文件接口和流</td></tr><tr><td><code>values/</code></td><td>Variant、数值、字符串、URL 和共享类型</td></tr></tbody></table><p>这些目录分别位于 <code>native/</code> 和 <code>src/</code> 下。只在某一层需要的实现保留在该层。<code>src/internal/</code> 保存 Native 加载器、包装器分配和共享内存转换等跨模块内部协议。</p><p><code>src/index.ts</code> 是 npm 公共入口，<code>native/addon.cc</code> 是 Native 模块注册入口。包级构建配置保留在根目录的 <code>binding.gyp</code>、<code>package.json</code> 和 <code>tsconfig.json</code>。</p><p>生成文件集中在 <code>src/generated/</code> 与 <code>native/generated/</code>。修改生成逻辑应编辑 <code>tools/codegen/</code> 中的生成器，再重新生成文件。</p><table tabindex="0"><thead><tr><th>工具目录</th><th>职责</th></tr></thead><tbody><tr><td><code>tools/build/</code></td><td>包内原生构建、Lua C++ 编译及编译数据库修正；仅在所属 Rush 工作区合并仓库 LSP 数据库</td></tr><tr><td><code>tools/codegen/</code></td><td>从上游头文件生成输入、事件、属性 ID 和样式绑定</td></tr><tr><td><code>tools/dependencies/</code></td><td>依赖版本、校验、下载和构建源清单</td></tr><tr><td><code>tools/dependencies/patches/</code></td><td>RmlUi、Lua、Debugger、数值、字符串和 rlottie 补丁</td></tr><tr><td><code>tools/performance/</code></td><td>性能测量及 Native 调用计数</td></tr><tr><td><code>tools/testing/</code></td><td>递归收集并执行运行时测试、保留剪贴板、验证 npm 源码包文件清单和构建依赖</td></tr></tbody></table><p><code>test/</code> 按模块归档运行时和类型用例，<code>test/native/</code> 按模块归档 C++ 对照程序及其构建脚本。构建脚本复用当前包的对象文件，输出目录由调用者指定为已有临时目录。</p><p><code>packages/sfmljs-rmlui-vscode/tools/testing/</code> 使用现有 VS Code 执行扩展集成验证； <code>tools/packaging/</code> 验证 VSIX 的内置客户端、语言服务器、语言资源和四语说明。 仓库级 Windows 工具链初始化位于 <code>tools/ci/</code>，供现有 Node.js CI 和独立 RmlUi CI 共用。</p><p><code>third_party/</code> 保留上游目录结构。<code>build/</code> 和 <code>dist/</code> 使用现有构建目录；源码迁移后，只移除已有新路径产物对应的旧产物。</p><p>目录迁移不代表 RmlUi 6.3 全量验收完成。<code>audit/6.3/</code> 的既有证据保留采集时的源码路径和哈希；查找这些历史路径时，使用<a href="https://github.com/XadillaX/node-sfml/blob/main/docs/rmlui/audit/6.3/source-layout-map.json" target="_blank" rel="noreferrer">目录迁移映射</a>。</p>',11)])])}const h=d(r,[["render",a]]);export{m as __pageData,h as default};
